package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api/catalog") public class CatalogController{private final JdbcClient db;public CatalogController(JdbcClient db){this.db=db;}public record Item(UUID id,String name,String description,String type,BigDecimal price,Integer durationMonths,String badge){}
 @GetMapping List<Item> list(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);var sql="select id,name,description,type,price,duration_months,null::varchar badge from amcservice.catalog_items where tenant_id=:t and active union all select id,name,description,'PACKAGE',price,duration_months,case when duration_months=12 then 'Popular care plan' end from amcservice.packages where tenant_id=:t and active order by type,name";return db.sql(sql).param("t",u.tenantId()).query(Item.class).list();}
 public record Manage(UUID id,@Pattern(regexp="PRODUCT|SERVICE|PACKAGE")String type,@NotBlank String name,String description,@DecimalMin("0")BigDecimal price,@Min(1)Integer durationMonths,boolean active,List<UUID> includedItemIds){}
 @GetMapping("/manage") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") List<Map<String,Object>> manage(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);var rows=new ArrayList<Map<String,Object>>();rows.addAll(db.sql("select id,type,name,description,price,duration_months,active,created_at from amcservice.catalog_items where tenant_id=:t order by type,name").param("t",u.tenantId()).query().listOfRows());for(var row:db.sql("select id,'PACKAGE' type,name,description,price,duration_months,active,created_at from amcservice.packages where tenant_id=:t order by name").param("t",u.tenantId()).query().listOfRows()){var copy=new LinkedHashMap<String,Object>(row);copy.put("included_item_ids",db.sql("select catalog_item_id from amcservice.package_items where package_id=:p order by catalog_item_id").param("p",row.get("id")).query(UUID.class).list());rows.add(copy);}return rows;}
 @PostMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN')") @ResponseStatus(HttpStatus.CREATED) @Transactional Map<String,Object> create(@AuthenticationPrincipal CurrentUser u,@Valid@RequestBody Manage r){CustomerController.tenant(u);var id=UUID.randomUUID();save(u,id,r,true);return Map.of("id",id);}
 @PutMapping("/{id}") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") @Transactional void update(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@Valid@RequestBody Manage r){CustomerController.tenant(u);save(u,id,r,false);}
 private void save(CurrentUser u,UUID id,Manage r,boolean create){if("PACKAGE".equals(r.type())){var months=r.durationMonths()==null?1:r.durationMonths();if(create)db.sql("insert into amcservice.packages(id,tenant_id,name,description,price,duration_months,active) values(:id,:t,:name,:description,:price,:months,:active)").param("id",id).param("t",u.tenantId()).param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",months).param("active",r.active()).update();else if(db.sql("update amcservice.packages set name=:name,description=:description,price=:price,duration_months=:months,active=:active where id=:id and tenant_id=:t").param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",months).param("active",r.active()).param("id",id).param("t",u.tenantId()).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Package not found");db.sql("delete from amcservice.package_items where package_id=:id").param("id",id).update();for(var item:Optional.ofNullable(r.includedItemIds()).orElse(List.of()))db.sql("insert into amcservice.package_items(package_id,catalog_item_id,quantity) select :p,id,1 from amcservice.catalog_items where id=:i and tenant_id=:t").param("p",id).param("i",item).param("t",u.tenantId()).update();}else{if(create)db.sql("insert into amcservice.catalog_items(id,tenant_id,type,name,description,price,duration_months,active) values(:id,:t,:type,:name,:description,:price,:months,:active)").param("id",id).param("t",u.tenantId()).param("type",r.type()).param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",r.durationMonths()).param("active",r.active()).update();else if(db.sql("update amcservice.catalog_items set type=:type,name=:name,description=:description,price=:price,duration_months=:months,active=:active where id=:id and tenant_id=:t").param("type",r.type()).param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",r.durationMonths()).param("active",r.active()).param("id",id).param("t",u.tenantId()).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Catalog item not found");}}
}
